const now = new Date();
const vnNow = new Date(now.toLocaleString('en-US', { timeZone: 'Asia/Ho_Chi_Minh' }));
const yesterday = new Date(vnNow);
yesterday.setDate(vnNow.getDate() - 1);

const pad = (n) => String(n).padStart(2, '0');
const fmtISO = (d) => `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
const fmtVN = (d) => `${pad(d.getDate())}/${pad(d.getMonth()+1)}/${d.getFullYear()}`;

return [{
  json: {
    yesterdayISO: fmtISO(yesterday),
    todayISO: fmtISO(vnNow),
    yesterdayVN: fmtVN(yesterday),
    todayVN: fmtVN(vnNow),
    yesterdayStart: `${fmtISO(yesterday)}T00:00:00.000+07:00`,
    todayStart: `${fmtISO(vnNow)}T00:00:00.000+07:00`
  }
}];

const dateInfo = $('Compute Dates').first().json;
const yesterdayVN = dateInfo.yesterdayVN;
const todayVN = dateInfo.todayVN;

const salesResults = $('Query Sales (Notion)').first().json.results || [];
const leadsResults = $('Query Leads (Notion)').first().json.results || [];

let tongDoanhThu = 0;
let tongDaThu = 0;
const salePerformance = {};
const productBreak = {};

for (const s of salesResults) {
  const p = s.properties || {};
  const giatri = p['Giá trị (VNĐ)']?.number || 0;
  const dathu = p['Đã thu (VNĐ)']?.number || 0;
  tongDoanhThu += giatri;
  tongDaThu += dathu;
  const sale = p['Sale']?.select?.name;
  if (sale) salePerformance[sale] = (salePerformance[sale] || 0) + giatri;
  const product = p['Sản phẩm/Khóa']?.select?.name;
  if (product) productBreak[product] = (productBreak[product] || 0) + giatri;
}

const leadSources = {};
for (const l of leadsResults) {
  const src = l.properties?.['Nguồn']?.select?.name || 'Chưa rõ';
  leadSources[src] = (leadSources[src] || 0) + 1;
}

const fmtVND = (n) => n.toLocaleString('vi-VN') + ' VNĐ';
const esc = (s) => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

let msg = `<b>📊 DRSKIN DASHBOARD — ${todayVN}</b>\n`;
msg += `<i>Báo cáo ngày ${yesterdayVN}</i>\n\n`;

msg += `<b>💰 DOANH THU</b>\n`;
msg += `• Ký hợp đồng: <b>${fmtVND(tongDoanhThu)}</b>\n`;
msg += `• Đã thu thực: <b>${fmtVND(tongDaThu)}</b>\n`;
msg += `• Số deal: <b>${salesResults.length}</b>\n\n`;

if (Object.keys(productBreak).length > 0) {
  msg += `<b>📦 Theo sản phẩm</b>\n`;
  for (const [prod, amt] of Object.entries(productBreak).sort((a,b)=>b[1]-a[1])) {
    msg += `  • ${esc(prod)}: ${fmtVND(amt)}\n`;
  }
  msg += `\n`;
}

const saleEntries = Object.entries(salePerformance).filter(([,amt]) => amt > 0);
if (saleEntries.length > 0) {
  msg += `<b>👤 Sale performance</b>\n`;
  for (const [s, amt] of saleEntries.sort((a,b)=>b[1]-a[1])) {
    msg += `  • ${esc(s)}: ${fmtVND(amt)}\n`;
  }
  msg += `\n`;
}

msg += `<b>🎯 LEADS MỚI</b>\n`;
msg += `• Tổng: <b>${leadsResults.length}</b> lead\n`;
for (const [src, n] of Object.entries(leadSources).sort((a,b)=>b[1]-a[1])) {
  msg += `  • ${esc(src)}: ${n}\n`;
}

if (salesResults.length === 0 && leadsResults.length === 0) {
  msg += `\n⚠️ Không có data cho ngày này. Check Notion xem Bích/Trân đã nhập chưa.`;
}

const genTime = new Date().toLocaleString('vi-VN', {timeZone:'Asia/Ho_Chi_Minh'});
msg += `\n\n🤖 <i>n8n auto • ${genTime}</i>`;

return [{
  json: {
    message: msg,
    salesCount: salesResults.length,
    leadsCount: leadsResults.length,
    totalRevenue: tongDoanhThu
  }
}];
